<?php
require_once __DIR__ . '/../config/database.php';
$pdo = db();
$sql = [];
$sql[] = "CREATE TABLE IF NOT EXISTS procurement_batches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, fiscal_year_id INT UNSIGNED NOT NULL, batch_no VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, status ENUM('draft','ordering','ordered','received_partial','received_complete','announced','closed') NOT NULL DEFAULT 'draft', purchase_date DATE NULL, expected_date DATE NULL, received_date DATE NULL, announcement_text TEXT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_batch_year_no (fiscal_year_id,batch_no), FOREIGN KEY (fiscal_year_id) REFERENCES fiscal_years(id)) ENGINE=InnoDB";
$sql[] = "CREATE TABLE IF NOT EXISTS procurement_batch_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, batch_id INT UNSIGNED NOT NULL, catalog_item_id INT UNSIGNED NOT NULL, item_name_snapshot VARCHAR(255) NOT NULL, unit_snapshot VARCHAR(100) NOT NULL, quantity_ordered DECIMAL(12,2) NOT NULL DEFAULT 0, quantity_received DECIMAL(12,2) NOT NULL DEFAULT 0, unit_price DECIMAL(12,2) NOT NULL DEFAULT 0, vendor_name VARCHAR(255) NULL, note TEXT NULL, FOREIGN KEY (batch_id) REFERENCES procurement_batches(id) ON DELETE CASCADE, FOREIGN KEY (catalog_item_id) REFERENCES catalog_items(id)) ENGINE=InnoDB";
$sql[] = "CREATE TABLE IF NOT EXISTS procurement_request_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, batch_id INT UNSIGNED NOT NULL, request_id INT UNSIGNED NOT NULL, request_item_id INT UNSIGNED NOT NULL, quantity_allocated DECIMAL(12,2) NOT NULL DEFAULT 0, quantity_delivered DECIMAL(12,2) NOT NULL DEFAULT 0, FOREIGN KEY (batch_id) REFERENCES procurement_batches(id) ON DELETE CASCADE, FOREIGN KEY (request_id) REFERENCES requests(id) ON DELETE CASCADE, FOREIGN KEY (request_item_id) REFERENCES request_items(id) ON DELETE CASCADE, UNIQUE KEY uq_batch_request_item (batch_id,request_item_id)) ENGINE=InnoDB";
$sql[] = "CREATE TABLE IF NOT EXISTS product_deliveries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, batch_id INT UNSIGNED NOT NULL, request_id INT UNSIGNED NOT NULL, member_id INT UNSIGNED NOT NULL, delivery_status ENUM('ready','partial','delivered','cancelled') NOT NULL DEFAULT 'ready', delivery_date DATETIME NULL, received_by_name VARCHAR(200) NULL, received_by_national_id VARCHAR(13) NULL, received_as ENUM('member','representative') NOT NULL DEFAULT 'member', representative_relation VARCHAR(100) NULL, evidence_file VARCHAR(255) NULL, receipt_number VARCHAR(100) NULL, delivered_by INT UNSIGNED NULL, note TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (batch_id) REFERENCES procurement_batches(id), FOREIGN KEY (request_id) REFERENCES requests(id), FOREIGN KEY (member_id) REFERENCES members(id)) ENGINE=InnoDB";
$sql[] = "CREATE TABLE IF NOT EXISTS product_delivery_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, delivery_id INT UNSIGNED NOT NULL, request_item_id INT UNSIGNED NOT NULL, quantity_due DECIMAL(12,2) NOT NULL DEFAULT 0, quantity_delivered DECIMAL(12,2) NOT NULL DEFAULT 0, FOREIGN KEY (delivery_id) REFERENCES product_deliveries(id) ON DELETE CASCADE, FOREIGN KEY (request_item_id) REFERENCES request_items(id)) ENGINE=InnoDB";
foreach ($sql as $statement) $pdo->exec($statement);
echo "Procurement/delivery migration v3 completed.\n";
